  "Peut-on prévoir un rendez-vous avant de s'engager ?": { en: "Can we schedule a meeting before committing?", ar: "هل يمكن تحديد موعد قبل الالتزام؟" },
  "Peut-on réserver la même équipe pour un prochain événement ?": { en: "Can we book the same team for a future event?", ar: "هل يمكن حجز نفس الفريق لمناسبة قادمة؟" },
