  "Veuillez sélectionner au moins une prestation": { en: "Please select at least one service", ar: "يرجى اختيار خدمة واحدة على الأقل" },
  "Veuillez sélectionner un type d'événement": { en: "Please select an event type", ar: "يرجى اختيار نوع المناسبة" },
